/* The Radar screen (knowledge-base/features/ops-control-panel.md §6). Dark by default; light follows html[data-theme].
   The sweep is slow and smooth on purpose (60 s a turn). Typefaces are the console's own (../styles/tokens.css). */

.radar-screen {
  --radar-ink: #f8fafc;
  --radar-ink-2: #ffffff;
  --radar-muted: #cbd5e1;
  --radar-dim: #94a3b8;
  --radar-faint: #7b8ba3;
  --radar-accent: #2563eb;
  --radar-amber: #ffb547;
  --radar-amber-ink: #ffc46b;
  --radar-lime: #93c5fd;
  --radar-resolved: #60a5fa;
  --radar-line: rgba(59, 130, 246, 0.16);
  --radar-detail: #93c5fd;
  --radar-stale-ink: #ffd9a0;
  --radar-on-pressed: #eff6ff;
  --radar-pill-ack: #bfdbfe;
  --radar-ring-label: rgba(147, 197, 253, 0.75);
  /* Flat page ground — no full-screen gradient; the scope disc keeps its own fill. */
  --radar-ground: #0a0f1a;
  --radar-head-bg: #101828;
  --radar-panel-bg: #101828;
  --radar-panel-hover: #16233a;
  --radar-disc: radial-gradient(circle, rgba(30, 58, 138, 0.45) 0%, rgba(16, 24, 40, 0.75) 55%, rgba(10, 15, 26, 0.95) 100%);
  --radar-axis-bg: rgba(16, 24, 40, 0.92);
  --radar-telemetry-bg: #101828;
  --radar-crt: none;
  --radar-sweep-blend: screen;
  --radar-display: "IBM Plex Sans", system-ui, sans-serif;
  --radar-mono: "IBM Plex Mono", ui-monospace, Menlo, monospace;
  position: relative;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  background: var(--radar-ground);
  color: var(--radar-ink);
  font-family: var(--radar-display);
  animation: none;
}
.radar-screen:fullscreen { overflow: auto; }
.radar-screen button { font-family: inherit; }
.radar-screen button:focus-visible, .radar-screen a:focus-visible { outline: 2px solid var(--radar-accent); outline-offset: 2px; }

/* The screen's own header — it stands alone in full screen. */
.radar-head { display: flex; align-items: center; gap: 20px; padding: 12px 32px; border-bottom: 1px solid var(--radar-line); background: var(--radar-head-bg); white-space: nowrap; }
.radar-head > * { flex-shrink: 0; }
.radar-head > .radar-head-gap { flex-shrink: 1; min-width: 0; }
/* the tenant's logo leads the header only in full screen, where the console's own header is gone */
.radar-head-logo { display: none; }
.radar-screen:fullscreen .radar-head-logo { display: flex; align-items: center; padding-right: 20px; border-right: 1px solid var(--radar-line); }
.radar-head-logo img { height: 30px; width: auto; max-width: 140px; object-fit: contain; }
.radar-head-gap { flex-grow: 1; }
/* The app header above already carries the airline's mark: the Radar's own shows only full screen, like the dCortex wordmark. */
.radar-head-tenant { display: none; height: 28px; width: 28px; border-radius: 8px; object-fit: cover; }
.radar-screen:fullscreen .radar-head-tenant { display: block; }
.radar-brand { display: flex; align-items: center; gap: 12px; line-height: 1.05; }
.radar-brand-title { font-family: var(--radar-mono); font-size: 13px; font-weight: 600; letter-spacing: 3px; color: var(--radar-muted); white-space: nowrap; }
.radar-brand-ring { fill: none; stroke: var(--radar-accent); stroke-width: 1.5; }
.radar-brand-ring--inner { stroke: rgba(59, 130, 246, 0.5); stroke-width: 1.2; }
.radar-brand-beam { stroke: var(--radar-accent); stroke-width: 2; }
.radar-brand-blip { fill: var(--radar-amber); }
.radar-feed-pill { display: flex; align-items: center; gap: 8px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 999px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1px; white-space: nowrap; }
.radar-feed-pill--stale { border-color: var(--radar-amber); color: var(--radar-stale-ink); }
.radar-feed-pill--stale .radar-live-dot { background: var(--radar-amber); box-shadow: 0 0 10px var(--radar-amber); }
.radar-live-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--radar-accent); box-shadow: 0 0 10px var(--radar-accent); animation: radar-livedot 1.2s infinite; }
.radar-clock { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.1; font-family: var(--radar-mono); }
.radar-clock-time { font-size: 8px; font-weight: 600; }
.radar-clock--utc .radar-clock-time { color: var(--radar-dim); }
.radar-clock-label { font-size: 10px; letter-spacing: 2px; color: var(--radar-dim); }
.radar-head-button { min-height: 36px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.35); border-radius: 8px; background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
.radar-screen:fullscreen .radar-head-button { display: none; }
.radar-modes { display: inline-flex; align-items: stretch; margin-left: auto; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; overflow: hidden; background: transparent; }
.radar-modes .radar-mode { min-height: 36px; padding: 6px 14px; border: 0; border-radius: 0; background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; line-height: 1.25; cursor: pointer; }
.radar-modes .radar-mode + .radar-mode { border-left: 1px solid rgba(59, 130, 246, 0.3); }
.radar-modes .radar-mode[aria-pressed="true"] { background: rgba(59, 130, 246, 0.14); color: var(--radar-ink); }
.radar-modes .radar-mode:focus-visible { outline: 2px solid var(--radar-accent); outline-offset: -2px; }
.radar-days { display: flex; align-items: center; gap: 6px; font-family: var(--radar-mono); font-size: 13px; letter-spacing: 1px; }
.radar-day-step { min-width: 36px; min-height: 36px; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; background: transparent; color: var(--radar-muted); cursor: pointer; }
.radar-day-step:disabled { opacity: 0.35; cursor: default; }
.radar-day-label { min-width: 92px; text-align: center; font-weight: 600; color: var(--radar-ink); }
.radar-day-live { min-height: 36px; padding: 6px 12px; border: 1px solid var(--radar-accent); border-radius: 8px; background: rgba(59, 130, 246, 0.14); color: var(--radar-ink); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
.radar-feed-pill--replay { border-color: var(--radar-amber); background: rgba(255, 181, 71, 0.1); color: var(--radar-stale-ink); }
.radar-tenant { padding-left: 16px; border-left: 1px solid var(--radar-line); font-size: 13px; font-weight: 600; letter-spacing: 1px; color: var(--radar-muted); }
/* a narrower screen drops what it can read elsewhere: the tenant (console header), the subtitle, then the UTC clock */
@media (max-width: 1280px) { .radar-tenant { display: none; } }
@media (max-width: 1040px) { .radar-clock--utc { display: none; } .radar-head { gap: 14px; padding: 10px 16px; } }

.radar-main { flex-grow: 1; display: grid; grid-template-columns: minmax(340px, 470px) minmax(0, 1fr); gap: clamp(28px, 4vw, 72px); padding: 24px 32px 28px; min-height: 0; }
@media (max-width: 1040px) { .radar-main { grid-template-columns: minmax(0, 1fr); gap: 28px; padding: 18px 16px 20px; } }

/* The feed. */
.radar-feed { display: flex; flex-direction: column; gap: 16px; min-width: 0; }
.radar-feed-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; }
.radar-eyebrow { display: block; font-family: var(--radar-mono); font-size: 11px; letter-spacing: 3px; color: var(--radar-dim); }
.radar-feed-head h1 { margin: 4px 0 0; font-size: 24px; font-weight: 600; letter-spacing: 1px; }
.radar-shown { font-family: var(--radar-mono); font-size: 12px; color: var(--radar-dim); text-align: right; }
.radar-x { flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; padding: 0; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 50%; background: transparent; color: var(--radar-muted); font-size: 17px; line-height: 1; cursor: pointer; }
.radar-x:hover { border-color: var(--radar-accent); color: var(--radar-ink); background: rgba(59, 130, 246, 0.1); }
.radar-locked { position: relative; }
/* the filtered list's own header: what is shown, and the × that clears it */
.radar-filterbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: -6px; padding: 6px 4px 6px 12px; border-radius: 8px; background: rgba(59, 130, 246, 0.06); }
.radar-locked-close { position: absolute; top: 12px; right: 12px; }
.radar-locked-meta { padding-right: 40px; }
.radar-no-match { margin: 16px 0; font-size: 13px; color: var(--radar-muted); }
.radar-link { padding: 0; border: 0; background: none; color: var(--radar-accent); font-size: inherit; text-decoration: underline; cursor: pointer; }

.radar-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; border: 1px solid var(--radar-line); border-radius: 10px; overflow: hidden; background: var(--radar-panel-bg); }
.radar-kpi { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; padding: 14px 14px 12px; border: 0; border-radius: 0; border-top: 2px solid transparent; border-right: 1px solid var(--radar-line); background: var(--radar-panel-bg); color: inherit; text-align: left; cursor: pointer; }
.radar-kpi:last-child { border-right: 0; }
.radar-kpi:hover { background: var(--radar-panel-hover); }
.radar-kpi[aria-pressed="true"] { background: rgba(59, 130, 246, 0.12); border-top-color: var(--radar-accent); }
.radar-kpi-value { font-size: 26px; font-weight: 600; line-height: 1; font-variant-numeric: tabular-nums; }
.radar-kpi-label { min-height: 2.6em; font-family: var(--radar-mono); font-size: 11px; line-height: 1.35; letter-spacing: 1px; color: var(--radar-muted); }
.radar-kpi--action { border-top-color: rgba(255, 181, 71, 0.7); }
.radar-kpi--action .radar-kpi-value { color: var(--radar-amber-ink); }
.radar-kpi--action .radar-kpi-label { color: var(--radar-stale-ink); }
.radar-kpi--action[aria-pressed="true"] { background: rgba(255, 181, 71, 0.12); border-top-color: var(--radar-amber); }
.radar-kpi--new .radar-kpi-value { color: var(--radar-accent); }
.radar-kpi--resolved .radar-kpi-value { color: var(--radar-dim); }

/* an even grid: every chip whole, rows aligned, however many fit across */
.radar-chips { display: grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); gap: 8px; }
.radar-chip { min-height: 32px; text-align: center; padding: 7px 14px; border-radius: 8px; border: 1px solid rgba(59, 130, 246, 0.22); background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 11px; font-weight: 600; letter-spacing: 1px; line-height: 1.25; white-space: nowrap; cursor: pointer; }
.radar-chip:hover { border-color: rgba(59, 130, 246, 0.4); }
.radar-screen .radar-chip, .radar-screen .radar-toolbar button { font-family: var(--radar-mono); }
.radar-chip--hot { color: var(--radar-amber-ink); }
.radar-chip[aria-pressed="true"] { background: rgba(59, 130, 246, 0.22); border-color: var(--radar-accent); color: var(--radar-on-pressed); }

.radar-locked { display: flex; flex-direction: column; gap: 10px; padding: 16px 18px; border-radius: 12px; border: 1px solid rgba(255, 181, 71, 0.5); background: linear-gradient(135deg, rgba(255, 181, 71, 0.1), rgba(59, 130, 246, 0.05)); }
.radar-locked-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; font-family: var(--radar-mono); font-size: 11px; letter-spacing: 2px; color: var(--radar-dim); }
.radar-locked-mark { color: var(--radar-amber-ink); }
.radar-locked-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding-right: 36px; }
.radar-locked-title { font-size: 21px; font-weight: 600; line-height: 1.2; }
.radar-locked-kind { font-size: 14px; font-weight: 400; line-height: 1.4; color: var(--radar-muted); }
.radar-locked-facts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 18px; }
.radar-locked-fact-label { display: block; margin-bottom: 2px; font-family: var(--radar-mono); font-size: 10px; letter-spacing: 0.8px; color: var(--radar-dim); }
.radar-locked-fact-value { font-size: 15px; }
.radar-locked-detail { font-size: 14px; line-height: 1.4; color: var(--radar-muted); }
.radar-locked-actions { display: flex; align-items: center; gap: 8px; }
.radar-primary { min-height: 44px; padding: 10px 16px; border: 1px solid var(--radar-accent); border-radius: 8px; background: var(--radar-accent); color: #ffffff; font-size: 13px; font-weight: 700; letter-spacing: 1.5px; cursor: pointer; }
.radar-secondary { display: inline-flex; align-items: center; min-height: 44px; box-sizing: border-box; padding: 10px 16px; border: 1px solid rgba(59, 130, 246, 0.45); border-radius: 8px; color: var(--radar-ink); font-size: 13px; font-weight: 600; letter-spacing: 1.5px; text-decoration: none; }
button.radar-secondary { background: transparent; cursor: pointer; font-family: inherit; }
button.radar-secondary:disabled { opacity: 0.6; cursor: default; }
.radar-secondary:hover { background: rgba(59, 130, 246, 0.08); }
button.radar-secondary { background: none; font-family: inherit; cursor: pointer; }
button.radar-secondary:hover { background: rgba(59, 130, 246, 0.08); }

.radar-stale { margin: 0; padding: 8px 12px; border-radius: 8px; border: 1px solid var(--radar-amber); background: rgba(255, 181, 71, 0.1); color: var(--radar-stale-ink); font-size: 13px; }
.radar-empty { margin: 24px 0; color: var(--radar-muted); }
.radar-ack-error { color: var(--radar-amber-ink); font-size: 12px; }
.radar-unplaced { margin: 0; font: 12px var(--radar-mono); color: var(--radar-faint); }

.radar-list { display: flex; flex-direction: column; max-height: 540px; overflow-y: auto; padding-right: 4px; border-top: 1px solid var(--radar-line); }
.radar-list::-webkit-scrollbar { width: 8px; }
.radar-list::-webkit-scrollbar-thumb { background: rgba(59, 130, 246, 0.25); border-radius: 4px; }
.radar-row { display: grid; grid-template-columns: 56px auto minmax(0, 1fr) auto; gap: 12px; align-items: center; width: 100%; min-height: 54px; padding: 9px 10px 9px 12px; border: 0; border-bottom: 1px solid rgba(59, 130, 246, 0.08); border-left: 2px solid transparent; border-radius: 0; background: transparent; color: inherit; text-align: left; cursor: pointer; }
.radar-row--flight { grid-template-columns: 56px minmax(0, 1fr) auto; }
/* a document row has no tag column (it's never a task) and its "when" is a full date (2026-10-13), not a clock — the
   default 56px first column is sized for a short age like "4m", so it wraps a date onto three lines without this */
.radar-row--expiry { grid-template-columns: 92px minmax(0, 1fr) auto; box-sizing: border-box; text-align: left; cursor: pointer; }
.radar-doc-detail { display: grid; gap: 10px; margin: 0; }
.radar-doc-detail-row { display: grid; grid-template-columns: 130px minmax(0, 1fr); gap: 12px; align-items: baseline; }
.radar-doc-detail-row dd { margin: 0; overflow-wrap: anywhere; }
.radar-row:hover { background: rgba(59, 130, 246, 0.05); }
.radar-row.is-selected { border-left-color: var(--radar-amber); background: rgba(255, 181, 71, 0.08); }
.radar-row--resolved { opacity: 0.62; }
.radar-row-when { display: flex; flex-direction: column; gap: 2px; font-family: var(--radar-mono); }
.radar-row-age { font-size: 14px; font-weight: 600; color: var(--radar-ink); }
.radar-row-clock { font-size: 11px; color: var(--radar-dim); }
.radar-row-text { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.radar-row-title { font-size: 14px; font-weight: 600; color: var(--radar-ink-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.radar-row-detail { font-size: 12px; color: var(--radar-detail); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.radar-tag { min-width: 62px; box-sizing: border-box; padding: 3px 6px; border-radius: 4px; font-family: var(--radar-mono); font-size: 10px; font-weight: 600; letter-spacing: 1.5px; text-align: center; white-space: nowrap; }
.radar-tag--action { background: rgba(255, 181, 71, 0.16); border: 1px solid rgba(255, 181, 71, 0.6); color: var(--radar-amber); }
.radar-tag--open { background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.45); color: var(--radar-lime); }
.radar-tag--resolved { background: rgba(59, 130, 246, 0.08); border: 1px solid rgba(59, 130, 246, 0.3); color: var(--radar-accent); }

.radar-pill { padding: 3px 7px; border-radius: 4px; font-family: var(--radar-mono); font-size: 10px; font-weight: 600; letter-spacing: 1.5px; white-space: nowrap; }
.radar-pill--new, .radar-pill--uncrewed { background: var(--radar-accent); color: #ffffff; }
.radar-pill--cancelled, .radar-pill--critical, .radar-pill--missing { background: var(--radar-amber); color: #1f1300; }
.radar-pill--ack, .radar-pill--delayed, .radar-pill--warning, .radar-pill--late { border: 1px solid var(--radar-lime); color: var(--radar-pill-ack); }
.radar-pill--resolved, .radar-pill--manual { border: 1px solid rgba(59, 130, 246, 0.18); color: var(--radar-faint); }

/* The scope panel. */
.radar-panel { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
/* One row, always: the heading never wraps into a second visible row, and the mode switch sits at its right, so a mode's
   longer note (bands vs ring) can neither change the row's height nor move the radar. The parts sit in the order they are
   given up when the row is short (title, range, on-scope chip, sweep, note): whatever does not fit wraps below the row and
   is clipped, so a part shows whole or not at all, in any language, and the note is cut with an ellipsis before it is
   dropped. The whole text is the heading's hover. */
.radar-toolbar { --radar-heading-h: 38px; display: flex; align-items: center; gap: 14px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1.5px; color: var(--radar-dim); }
.radar-toolbar-info { flex: 1 1 auto; min-width: 0; display: flex; flex-wrap: wrap; align-content: flex-start; align-items: center; column-gap: 14px; row-gap: 14px; height: var(--radar-heading-h); overflow: hidden; white-space: nowrap; }
.radar-toolbar-info::before { content: ""; order: -1; flex: 0 0 0; height: var(--radar-heading-h); margin-right: -14px; }
.radar-toolbar-info > * { flex-shrink: 0; }
.radar-toolbar-info > .radar-toolbar-note { flex: 1 1 12ch; min-width: 0; max-width: max-content; overflow: hidden; text-overflow: ellipsis; }
.radar-toolbar .radar-modes { flex-shrink: 0; margin-left: auto; }
.radar-toolbar-title { font-family: var(--radar-display); font-size: 15px; font-weight: 600; letter-spacing: 3px; color: var(--radar-ink); }
.radar-toolbar-sweep { display: flex; align-items: center; gap: 6px; }
.radar-toolbar-only { padding: 2px 8px; border: 1px solid rgba(255, 181, 71, 0.45); border-radius: 4px; color: var(--radar-amber-ink); }
.radar-toolbar-sweep .radar-live-dot { width: 7px; height: 7px; animation: none; }
.radar-toolbar button { min-height: 40px; padding: 8px 14px; border: 1px solid rgba(59, 130, 246, 0.35); border-radius: 8px; background: transparent; color: var(--radar-muted); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
.radar-toolbar button[aria-pressed="true"] { background: rgba(59, 130, 246, 0.2); border-color: var(--radar-accent); color: var(--radar-on-pressed); }

/* The scope is the largest square, at most 800px, that fits the box it is given; the box takes the panel's height left
   between the heading and the telemetry strip (see "The Radar fits its window" below), so the strip is never pushed
   below the fold and nothing here depends on a guess at the other rows' heights. */
.radar-scope-fit { flex: 1 1 0; min-height: 240px; container-type: size; }
.radar-scope { position: relative; width: min(100cqw, 100cqh, 800px); aspect-ratio: 1 / 1; margin: 0 auto; container-type: inline-size; }
.radar-disc { position: absolute; inset: 8%; border-radius: 50%; background: var(--radar-disc); box-shadow: 0 0 60px rgba(59, 130, 246, 0.18), inset 0 0 80px rgba(0, 0, 0, 0.35); }
.radar-svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.radar-ring { fill: none; stroke: rgba(59, 130, 246, 0.2); stroke-width: 1.4; }
.radar-ring--rim { stroke: rgba(59, 130, 246, 0.55); stroke-width: 2; }
.radar-ring--now { fill: rgba(59, 130, 246, 0.07); stroke: rgba(59, 130, 246, 0.45); stroke-width: 1.6; animation: radar-now 2.4s ease-in-out infinite; }
.radar-spoke { stroke: rgba(59, 130, 246, 0.16); stroke-width: 1.2; stroke-dasharray: 3 7; }
.radar-sector-edge { stroke: rgba(59, 130, 246, 0.2); stroke-width: 1.2; }
.radar-ticks { stroke: rgba(59, 130, 246, 0.35); stroke-width: 1.4; }
.radar-ring--core { fill: rgba(255, 176, 32, 0.08); stroke: rgba(255, 176, 32, 0.55); stroke-width: 1.6; stroke-dasharray: 6 5; }
.radar-ring-label { fill: var(--radar-ring-label); font: 500 14px var(--radar-mono); letter-spacing: 1px; }
.radar-wedge { fill: rgba(59, 130, 246, 0.08); stroke: rgba(59, 130, 246, 0.35); stroke-width: 1; }
.radar-lockline { stroke: var(--radar-amber); stroke-width: 1.6; stroke-dasharray: 6 6; animation: radar-dash 1s linear infinite; }

.radar-centre, .radar-centre-ping { position: absolute; left: 50%; top: 50%; box-sizing: border-box; width: 14px; height: 14px; margin: -7px 0 0 -7px; border-radius: 50%; }
.radar-centre { background: #bfdbfe; box-shadow: 0 0 18px var(--radar-accent); }
.radar-centre-ping { border: 1.5px solid var(--radar-accent); animation: radar-ping 3s ease-out infinite; }

.radar-sweep {
  position: absolute; inset: 8%; border-radius: 50%; pointer-events: none; mix-blend-mode: var(--radar-sweep-blend);
  background: conic-gradient(from 0deg, rgba(59, 130, 246, 0) 0deg, rgba(59, 130, 246, 0) 250deg, rgba(59, 130, 246, 0.05) 300deg, rgba(59, 130, 246, 0.16) 335deg, rgba(59, 130, 246, 0.42) 357deg, rgba(191, 219, 254, 0.95) 359.4deg, rgba(59, 130, 246, 0) 360deg);
  animation-name: radar-sweep; animation-timing-function: linear; animation-iteration-count: infinite;
}

.radar-blip { position: absolute; width: 30px; height: 30px; margin: -15px 0 0 -15px; padding: 0; border: 0; background: transparent; display: flex; align-items: center; justify-content: center; cursor: pointer; }
.radar-blip--action { color: var(--radar-amber); }
.radar-blip--open { color: var(--radar-lime); }
.radar-blip--resolved { color: var(--radar-resolved); }
.radar-blip-dot { width: 13px; height: 13px; border-radius: 50%; background: currentColor; box-shadow: none; animation-name: radar-glow; animation-timing-function: linear; animation-iteration-count: infinite; }
.radar-blip--open .radar-blip-dot { width: 11px; height: 11px; }
.radar-blip--resolved .radar-blip-dot { width: 9px; height: 9px; }
.radar-reticle { position: absolute; width: 30px; height: 30px; margin: -15px 0 0 -15px; pointer-events: none; }
.radar-reticle svg { width: 30px; height: 30px; fill: none; stroke: var(--radar-amber); stroke-width: 3.5; filter: drop-shadow(0 0 4px rgba(255, 181, 71, 0.6)); animation: radar-spin 6s linear infinite; }

/* labels scale with the scope (container units), so a small scope never piles them onto the rings */
.radar-axis { position: absolute; transform: translate(-50%, -50%); padding: 0.35em 0.7em; border-radius: 6px; border: 1px solid transparent; background: var(--radar-axis-bg); color: var(--radar-dim); font-family: var(--radar-display); font-size: clamp(9px, 1.55cqi, 12px); font-weight: 600; letter-spacing: 0.12em; line-height: 1.2; text-transform: uppercase; text-align: center; white-space: nowrap; cursor: pointer; }
.radar-axis:hover { border-color: var(--radar-line); color: var(--radar-muted); }
.radar-axis--hot { color: var(--radar-amber-ink); }
.radar-axis[aria-pressed="true"] { background: rgba(59, 130, 246, 0.18); border-color: var(--radar-accent); color: var(--radar-ink); }
.radar-axis-count { display: block; margin-top: 2px; font-family: var(--radar-mono); font-size: 0.85em; font-weight: 500; letter-spacing: 0.08em; color: var(--radar-faint); }
.radar-axis--hot .radar-axis-count { color: var(--radar-amber); }

.radar-telemetry { display: flex; flex-direction: column; gap: 8px; padding: 12px 16px 10px; border-radius: 10px; border: 1px solid rgba(59, 130, 246, 0.14); background: var(--radar-telemetry-bg); }
.radar-scrub { width: 100%; margin: 0; accent-color: var(--radar-amber); }
.radar-arrivals { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.radar-arrivals-title { font-family: var(--radar-mono); font-size: 10px; letter-spacing: 2px; color: var(--radar-dim); }
.radar-arrivals svg { display: block; width: 100%; height: 40px; }
.radar-bar { fill: rgba(59, 130, 246, 0.75); }
.radar-bar--action { fill: var(--radar-amber); }
.radar-bar--empty { fill: rgba(59, 130, 246, 0.2); }
.radar-arrivals-axis { display: flex; justify-content: flex-end; font-family: var(--radar-mono); font-size: 10px; letter-spacing: 1.5px; color: var(--radar-faint); }
.radar-telemetry-read { padding-top: 8px; border-top: 1px solid rgba(59, 130, 246, 0.08); font-family: var(--radar-mono); font-size: 10.5px; letter-spacing: 1.5px; color: var(--radar-faint); }

/* The CRT: scanlines and a vignette over everything, never in the way of a click. Softened / off in light. */
.radar-crt {
  position: absolute; inset: 0; pointer-events: none;
  background: var(--radar-crt);
}

@keyframes radar-sweep { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
/* the dot brightens as the beam passes (0%), then fades until the next turn. No halo: a shadow outside the dot stacks into a wash when many sit together. */
@keyframes radar-glow { 0%, 8% { opacity: 1; } 100% { opacity: 0.4; } }
@keyframes radar-ping { 0% { transform: scale(0.2); opacity: 0.8; } 100% { transform: scale(9); opacity: 0; } }
@keyframes radar-now { 0%, 100% { fill-opacity: 0.55; } 50% { fill-opacity: 1; } }
@keyframes radar-livedot { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }
@keyframes radar-scroll { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@keyframes radar-dash { to { stroke-dashoffset: -12; } }
@keyframes radar-spin { to { transform: rotate(360deg); } }
@keyframes radar-flicker { 0%, 100% { opacity: 0.97; } 47% { opacity: 0.93; } 50% { opacity: 0.99; } 53% { opacity: 0.94; } }

/* Light theme — same layout; paper grounds, darker ink, no CRT/flicker. Driven by the ops header toggle (html[data-theme]). */
html[data-theme="light"] .radar-screen {
  --radar-ink: #0f172a;
  --radar-ink-2: #020617;
  --radar-muted: #334155;
  --radar-dim: #475569;
  --radar-faint: #64748b;
  --radar-accent: #2563eb;
  --radar-amber: #b45309;
  --radar-amber-ink: #92400e;
  --radar-lime: #1d4ed8;
  --radar-resolved: #475569;
  --radar-line: rgba(37, 99, 235, 0.18);
  --radar-detail: #1d4ed8;
  --radar-stale-ink: #92400e;
  --radar-on-pressed: #1e3a8a;
  --radar-pill-ack: #1e40af;
  --radar-ring-label: rgba(37, 99, 235, 0.7);
  --radar-ground: #f8fafc;
  --radar-head-bg: #ffffff;
  --radar-panel-bg: #ffffff;
  --radar-panel-hover: #f1f5f9;
  --radar-disc: radial-gradient(circle, rgba(191, 219, 254, 0.85) 0%, rgba(226, 232, 240, 0.95) 55%, rgba(241, 245, 249, 1) 100%);
  --radar-axis-bg: #ffffff;
  --radar-telemetry-bg: #ffffff;
  --radar-crt: none;
  --radar-sweep-blend: multiply;
  animation: none;
}
html[data-theme="light"] .radar-disc { box-shadow: 0 0 40px rgba(37, 99, 235, 0.12), inset 0 0 40px rgba(148, 163, 184, 0.25); }
html[data-theme="light"] .radar-centre { background: #2563eb; }
html[data-theme="light"] .radar-primary { color: #ffffff; }
html[data-theme="light"] .radar-pill--new, html[data-theme="light"] .radar-pill--uncrewed { color: #ffffff; }
html[data-theme="light"] .radar-pill--cancelled, html[data-theme="light"] .radar-pill--critical, html[data-theme="light"] .radar-pill--missing { color: #ffffff; }
html[data-theme="light"] .radar-kpi[aria-pressed="true"] { background: rgba(37, 99, 235, 0.1); }
html[data-theme="light"] .radar-modes .radar-mode[aria-pressed="true"],
